const results = await Promise.allSettled([
  tools.exec_command({cmd:"ls -la /app && ls -la /app/output 2>/dev/null || true",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"sed -n '1,260p' /opt/tools/rcb_brush.py",workdir:"/app",yield_time_ms:10000,max_output_tokens:6000}),
  tools.exec_command({cmd:"file /app/target.png && sed -n '1,160p' /app/NOTICE-exemplar.md",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000})
]);
for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

const results = await Promise.allSettled([
  tools.view_image({path:"/app/target.png",detail:"original"}),
  tools.exec_command({cmd:"rg -n \"class WangBrush|def score|def strokes|def save_trajectory|def move_tip|def wells|def record_start|def reset|def target_image|def ink\\(\" /opt/tools/rcb_brush.py",workdir:"/app",yield_time_ms:10000,max_output_tokens:3000}),
  tools.exec_command({cmd:"python - <<'PY'\nimport json\nprint(json.load(open('/app/instance.json')))\nPY",workdir:"/app",yield_time_ms:10000,max_output_tokens:3000})
]);
for (const r of results) { if(r.status==="fulfilled") { if(r.value.image_url) image(r.value.image_url); else text(r.value.output); } else text(String(r.reason)); }
